function issueTaxiCall(){taxiCall++;taxiPhase='pickup';taxiNextCall=0;let pickup=pointAt(taxiCall*7+5,taxiCall+2);for(let i=0;i<8&&Math.hypot(pickup.x-player.x,pickup.y-player.y)<520;i++)pickup=pointAt(taxiCall*7+9+i,taxiCall+3);let drop=pointAt(taxiCall*11+17,taxiCall+4);for(let i=0;i<8&&Math.hypot(drop.x-pickup.x,drop.y-pickup.y)<700;i++)drop=pointAt(taxiCall*11+24+i,taxiCall+5);taxiPickup=pickup;taxiDrop=drop;taxiPassenger=taxiNames[(taxiCall*3+1)%taxiNames.length];taxiFare=Math.max(45,Math.round(Math.hypot(drop.x-pickup.x,drop.y-pickup.y)/6)+25);say('DISPATCH: PICK UP '+taxiPassenger.toUpperCase()+' IN '+districtAt(pickup.x,pickup.y)+'.',3.5);updateHud();}
