function nearestRoadNode(x,y){let ix=0,iy=0;for(let i=1;i<ROAD_X.length;i++)if(Math.abs(ROAD_X[i]-x)<Math.abs(ROAD_X[ix]-x))ix=i;for(let i=1;i<ROAD_Y.length;i++)if(Math.abs(ROAD_Y[i]-y)<Math.abs(ROAD_Y[iy]-y))iy=i;return{ix,iy,x:ROAD_X[ix],y:ROAD_Y[iy]};}
function findSafeRoadNode(origin,minDistance=0,avoidTraffic=true){let best=null,bestDistance=Infinity;for(const x of ROAD_X)for(const y of ROAD_Y){const d=Math.hypot(x-origin.x,y-origin.y);if(d<minDistance||d>=bestDistance||isBlocked(x,y,14))continue;if(avoidTraffic&&carInPath(x,y,23))continue;best={x,y};bestDistance=d;}return best;}
function findNearbyOfficerSpot(origin){for(const radius of [55,70,85])for(let i=0;i<8;i++){const a=i*Math.PI/4,x=origin.x+Math.cos(a)*radius,y=origin.y+Math.sin(a)*radius;if(!isBlocked(x,y,8)&&!personInPath(x,y,8))return{x,y};}return findSafeRoadNode(origin,18,false)||{x:origin.x+45,y:origin.y};}
function streetRoute(from,target){const start=nearestRoadNode(from.x,from.y),end=nearestRoadNode(target.x,target.y),key=(ix,iy)=>ix+','+iy,queue=[[start.ix,start.iy]],previous=new Map([[key(start.ix,start.iy),null]]);for(let q=0;q<queue.length&&!previous.has(key(end.ix,end.iy));q++){const [ix,iy]=queue[q];for(const [nx,ny] of [[ix+1,iy],[ix-1,iy],[ix,iy+1],[ix,iy-1]]){if(nx<0||nx>=ROAD_X.length||ny<0||ny>=ROAD_Y.length||previous.has(key(nx,ny)))continue;const ax=ROAD_X[ix],ay=ROAD_Y[iy],bx=ROAD_X[nx],by=ROAD_Y[ny],steps=Math.ceil(Math.hypot(bx-ax,by-ay)/40);let clear=true;for(let i=1;i<=steps;i++){const t=i/steps;if(isWater(ax+(bx-ax)*t,ay+(by-ay)*t)){clear=false;break;}}if(clear){previous.set(key(nx,ny),[ix,iy]);queue.push([nx,ny]);}}}if(!previous.has(key(end.ix,end.iy))){const direct=[{x:start.x,y:start.y}];if(Math.hypot(target.x-start.x,target.y-start.y)>1)direct.push({x:target.x,y:target.y});return direct;}const nodes=[];let at=[end.ix,end.iy];while(at){nodes.push({x:ROAD_X[at[0]],y:ROAD_Y[at[1]]});at=previous.get(key(at[0],at[1]));}nodes.reverse();if(Math.hypot(nodes[0].x-from.x,nodes[0].y-from.y)<1)nodes.shift();if(Math.hypot(target.x-end.x,target.y-end.y)>1)nodes.push({x:target.x,y:target.y});return nodes.length?nodes:[{x:target.x,y:target.y}];}
function planDemoRoute(target){demoPath=streetRoute(player,target);demoGoalKey=phase+':'+target.x+':'+target.y;if(!demoPath.length&&Math.hypot(player.x-target.x,player.y-target.y)>18)demoPath.push({x:target.x,y:target.y});}
function driveDemo(dt){if(!demoMode||!active)return;demoSteering=null;keys.clear();const moved=Math.hypot(player.x-demoLastX,player.y-demoLastY);if(moved>1)demoBlockedFor=0;else if(Math.abs(player.speed)>22)demoBlockedFor+=dt;demoLastX=player.x;demoLastY=player.y;if(!player.car)player.car=true;const route=getRoute(),target=phase===0?route.start:route.end,key=phase+':'+target.x+':'+target.y;if(key!==demoGoalKey)planDemoRoute(target);if(demoPath.length&&Math.hypot(player.x-demoPath[0].x,player.y-demoPath[0].y)<18)demoPath.shift();if(!demoPath.length){player.speed=0;demoBlockedFor=0;return;}const waypoint=demoPath[0],dx=waypoint.x-player.x,dy=waypoint.y-player.y,angle=Math.atan2(dy,dx);player.a=angle;const probeX=player.x+Math.cos(angle)*42,probeY=player.y+Math.sin(angle)*42,blocked=carInPath(probeX,probeY,19)||personInPath(probeX,probeY,29);if(blocked)demoBlockedFor+=dt;if(demoBlockedFor>1.15&&demoGhostTimer<=0){demoGhostTimer=1.8;demoBlockedFor=0;player.speed=0;say('AUTO-PILOT IS TAKING THE CLEAR LANE.',1.6);}if(blocked&&demoGhostTimer<=0){player.speed=0;return;}demoSteering=angle;}
