function hash(n){const x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x);}
function riverY(x){return 1780+Math.sin(x/710)*115+Math.sin(x/260)*28;}
function isMainRiver(x,y){return Math.abs(y-riverY(x))<145;}
function isElkRiver(x,y){if(y>1770)return false;const cx=3210-260*(y/1770)+Math.sin(y/260)*44;return Math.abs(x-cx)<78;}
function isWater(x,y){const main=isMainRiver(x,y),bridge=BRIDGE_X.some(b=>Math.abs(x-b)<54);if(main&&!bridge)return true;const elk=isElkRiver(x,y),elkBridge=ELK_BRIDGE_Y.some(b=>Math.abs(y-b)<48);return elk&&!elkBridge;}
function isBlocked(x,y,r=9){if(x<15||y<15||x>WORLD.w-15||y>WORLD.h-15||isWater(x,y))return true;for(const b of LOTS)if(x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)return true;return false;}
function carInPath(x,y,r=10){for(const c of traffic)if(Math.hypot(x-c.x,y-c.y)<r+17)return true;for(const c of police)if(Math.hypot(x-c.x,y-c.y)<r+17)return true;for(let i=0;i<ROAD_X.length;i++)for(let j=0;j<ROAD_Y.length;j++)if((i+j)%3===0){const px=ROAD_X[i]+(i%2?37:-37),py=ROAD_Y[j]+32;if(Math.hypot(x-px,y-py)<r+17)return true;}return false;}
function personInPath(x,y,r=8,ignore=null){for(const n of npcs)if(n!==ignore&&Math.hypot(x-n.x,y-n.y)<r+9)return true;return false;}
function impactAt(x,y,color='#ffcf62'){impact={x,y,color,until:time+.32};}
function bumpMessage(x,y,message){impactAt(x,y);if(demoMode){demoBlockedFor+=.35;demoBumpCount++;if(demoBumpCount>=3){demoGhostTimer=1.8;demoBumpCount=0;demoBlockedFor=0;player.speed=0;say('AUTO-PILOT IS TAKING THE CLEAR LANE.',1.6);}}if(time-lastBump>.85){lastBump=time;say(message,1.1);}}
function initWorld(){for(let i=0;i<48;i++){const p=pointAt(i,2);drops.push({x:p.x+(hash(i)*76-38),y:p.y+(hash(i+14)*76-38),got:false});}for(let i=0;i<78;i++){const p=pointAt(i+5,3);npcs.push({x:p.x+(hash(i+50)*66-33),y:p.y+(hash(i+90)*68-34),a:hash(i+22)*6.28,t:hash(i+32)*3,shirt:['#e27652','#e9c55f','#76a6a0','#b58bd1'][i%4]});}for(let i=0;i<34;i++){const horizontal=i%2===0,road=horizontal?ROAD_Y[Math.floor(hash(i+83)*ROAD_Y.length)]:ROAD_X[Math.floor(hash(i+19)*ROAD_X.length)];let x=horizontal?hash(i+47)*WORLD.w:road,y=horizontal?road:hash(i+91)*WORLD.h;if(isWater(x,y)){for(let n=0;n<24&&isWater(x,y);n++){if(horizontal)x=(x+125)%WORLD.w;else y=(y+145)%WORLD.h;}}traffic.push({id:i,x,y,axis:horizontal?'x':'y',dir:hash(i+7)>.5?1:-1,speed:34+hash(i+55)*28,currentSpeed:0,turnCooldown:hash(i+200)*2,color:['#bd6150','#d4ae59','#537f88','#9c768e','#d2d0b4'][i%5]});}}
initWorld();
function lotType(b){const {gx,gy,x,y,w,h}=b,cx=x+w/2,cy=y+h/2,area=districtAt(cx,cy);if(gx===7&&gy===2)return'capitol';if(gx===5&&gy===2)return'market';if(gx===2&&gy===1)return'stadium';if(gx===4&&gy===3)return'rail';if((gx*17+gy*11)%13===0)return'park';if(area==='SOUTH HILLS')return'hills';if(area==='KANAWHA CITY')return'homes';if(area==='WEST SIDE'||area==='ELK CITY')return(gx+gy)%4===0?'yard':'homes';if(area==='DOWNTOWN'||area==='EAST END')return'office';return(gx+gy)%3===0?'park':'shops';}
function drawHouse(x,y,w,h,color){ctx.fillStyle='#393831';ctx.fillRect(x+5,y+6,w,h);ctx.fillStyle=color;ctx.fillRect(x,y,w,h);ctx.fillStyle='#bba883';ctx.fillRect(x+4,y+4,w-8,5);ctx.fillStyle='#3b4440';ctx.fillRect(x+w*.2,y+h*.26,w*.22,h*.2);ctx.fillRect(x+w*.58,y+h*.26,w*.22,h*.2);ctx.fillStyle='#796b53';ctx.fillRect(x+w*.43,y+h*.62,w*.16,h*.38);ctx.fillStyle='#d9c794';ctx.fillRect(x+3,y+h-5,w-6,3);}
