 if(type==='park'||type==='hills'){ctx.fillStyle=type==='hills'?'#52694e':'#71845d';ctx.fillRect(bx+7,by+7,bw-14,bh-14);ctx.strokeStyle=type==='hills'?'#8b9571':'#c2b48b';ctx.lineWidth=type==='hills'?3:5;ctx.beginPath();ctx.moveTo(bx+12,cy);ctx.lineTo(cx-18,cy);ctx.lineTo(cx+15,by+14);ctx.lineTo(cx+25,by+bh-12);ctx.lineTo(bx+bw-12,by+bh-12);ctx.stroke();if(type==='park'){ctx.fillStyle='#527782';ctx.beginPath();ctx.ellipse(cx+bw*.2,cy,Math.min(31,bw*.12),Math.min(17,bh*.08),-.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d6c997';ctx.fillRect(cx-10,cy-7,20,14);ctx.fillStyle='#795c43';ctx.fillRect(cx-6,cy-4,12,9);}for(let i=0;i<7;i++){const tx=bx+18+hash(gx*40+gy*11+i)*Math.max(10,bw-36),ty=by+16+hash(gx*13+gy*33+i)*Math.max(10,bh-32);ctx.fillStyle='#403e32';ctx.fillRect(tx-4,ty+5,9,8);ctx.fillStyle=['#56734b','#688454','#82935f'][i%3];ctx.fillRect(tx-8,ty-3,17,13);ctx.fillStyle='#9aaa6b';ctx.fillRect(tx-4,ty-2,8,5);}}
 else if(type==='capitol'){ctx.fillStyle='#728466';ctx.fillRect(bx+6,by+6,bw-12,bh-12);ctx.fillStyle='#c9bd9a';ctx.fillRect(cx-bw*.34,cy-bh*.28,bw*.68,bh*.56);ctx.fillStyle='#e1d5b4';ctx.fillRect(cx-bw*.3,cy-bh*.24,bw*.6,bh*.08);for(let i=0;i<7;i++){ctx.fillStyle='#f0e4c4';ctx.fillRect(cx-bw*.26+i*bw*.085,cy-bh*.12,4,bh*.28);}ctx.fillStyle='#d0c4a3';ctx.fillRect(cx-bw*.4,cy+bh*.23,bw*.8,8);ctx.fillStyle='#ddd3b5';ctx.beginPath();ctx.ellipse(cx,cy-bh*.2,20,17,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d9b95e';ctx.beginPath();ctx.arc(cx,cy-bh*.22,8,Math.PI,0);ctx.fill();ctx.fillRect(cx-1,cy-bh*.42,2,8);ctx.fillStyle='#d3c3a0';ctx.fillRect(bx+8,by+bh*.72,bw-16,5);}
