 ctx.fillStyle='#8c907e';ctx.beginPath();for(let y=0;y<=1770;y+=45){const x=3210-260*(y/1770)+Math.sin(y/260)*44+78;if(y===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}for(let y=1770;y>=0;y-=45)ctx.lineTo(3210-260*(y/1770)+Math.sin(y/260)*44-78,y);ctx.closePath();ctx.fill();ctx.fillStyle='#285865';ctx.beginPath();for(let y=0;y<=1770;y+=45){const x=3210-260*(y/1770)+Math.sin(y/260)*44+68;if(y===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}for(let y=1770;y>=0;y-=45)ctx.lineTo(3210-260*(y/1770)+Math.sin(y/260)*44-68,y);ctx.closePath();ctx.fill();
 for(const bx of BRIDGE_X){const cy=riverY(bx);ctx.fillStyle='#373e3a';ctx.fillRect(bx-52,cy-166,104,332);ctx.fillStyle='#74796b';ctx.fillRect(bx-46,cy-162,92,324);ctx.fillStyle='#555c55';ctx.fillRect(bx-35,cy-160,70,320);ctx.fillStyle='#d2c37c';for(let yy=cy-146;yy<cy+146;yy+=38)ctx.fillRect(bx-2,yy,4,20);ctx.fillStyle='#c8c1a1';ctx.fillRect(bx-48,cy-155,4,310);ctx.fillRect(bx+44,cy-155,4,310);ctx.fillStyle='#e0cb85';for(let yy=cy-130;yy<cy+130;yy+=42){ctx.fillRect(bx-50,yy,4,7);ctx.fillRect(bx+46,yy,4,7);}}
