function drawWorld(){ctx.save();ctx.translate(-camera.x,-camera.y);drawCity();drawCityDetails();for(let i=0;i<ROAD_X.length;i++)for(let j=0;j<ROAD_Y.length;j++)if((i+j)%3===0){const xx=ROAD_X[i]+(i%2?37:-37),yy=ROAD_Y[j]+32;drawCar(xx,yy,Math.PI/2,['#b75a4c','#d0ad60','#426e78','#8c5e83'][(i+j)%4]);}traffic.forEach(c=>drawCar(c.x,c.y,c.axis==='x'?(c.dir>0?0:Math.PI):(c.dir>0?Math.PI/2:-Math.PI/2),c.color));drops.forEach(d=>{if(!d.got){const pulse=1+Math.sin(time*5+d.x)*.22;ctx.fillStyle='#e9ca6025';ctx.beginPath();ctx.arc(d.x,d.y,12*pulse,0,Math.PI*2);ctx.fill();ctx.fillStyle='#392f23';ctx.fillRect(d.x-7,d.y-5,14,11);ctx.fillStyle='#e9ca60';ctx.fillRect(d.x-6,d.y-5,12,9);ctx.fillStyle='#fff0a6';ctx.fillRect(d.x-4,d.y-4,8,2);ctx.fillStyle='#5b4923';ctx.font='bold 8px monospace';ctx.fillText('$',d.x-2,d.y+3);}});npcs.forEach(n=>drawPerson(n.x,n.y,n.shirt));if(active&&!completed&&(!taxiMode||taxiPhase!=='waiting')){const r=getRoute(),isPickup=taxiMode?taxiPhase==='pickup':phase===0,p=taxiMode?(isPickup?taxiPickup:taxiDrop):(isPickup?r.start:r.end),rad=18+Math.sin(time*5)*3;ctx.fillStyle=isPickup?'#f0ca5c22':'#c3ed5922';ctx.beginPath();ctx.arc(p.x,p.y,rad+13,0,Math.PI*2);ctx.fill();ctx.strokeStyle=isPickup?'#f0ca5c':'#c3ed59';ctx.lineWidth=3;ctx.setLineDash([7,5]);ctx.beginPath();ctx.arc(p.x,p.y,rad+5,-time*.4,Math.PI*2-time*.4);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=isPickup?'#e3b747':'#b9e34a';ctx.fillRect(p.x-6,p.y-6,12,12);ctx.fillStyle='#fff5d2';ctx.fillRect(p.x-2,p.y-2,4,4);if(taxiMode&&isPickup)drawPerson(p.x,p.y-18,'#edd28a');ctx.fillStyle='#f6f0d8';ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillText(taxiMode?(isPickup?'PICK UP RIDER':'DROP RIDER'):(isPickup?'PICK UP':'DROP OFF'),p.x,p.y-32);}police.forEach(p=>{drawCar(p.onFoot?p.carX:p.x,p.onFoot?p.carY:p.y,p.onFoot?p.carA:p.a,'#e5e7df',true);if(p.onFoot)drawPoliceOfficer(p.x,p.y,p.a);});if(player.car)drawCar(player.x,player.y,player.a,taxiMode?'#d6af3b':'#cb5c48',false,taxiMode);else drawPerson(player.x,player.y,'#e1bf69');if(impact&&time<impact.until){const f=(impact.until-time)/.32;ctx.save();ctx.globalAlpha=f;ctx.strokeStyle=impact.color;ctx.lineWidth=2;ctx.beginPath();ctx.arc(impact.x,impact.y,8+(1-f)*14,0,Math.PI*2);ctx.stroke();for(let i=0;i<4;i++){const a=i*Math.PI/2+time*9;ctx.beginPath();ctx.moveTo(impact.x+Math.cos(a)*7,impact.y+Math.sin(a)*7);ctx.lineTo(impact.x+Math.cos(a)*15,impact.y+Math.sin(a)*15);ctx.stroke();}ctx.restore();}ctx.restore();drawMiniMap();}
function movePlayer(dt){if(arrestPending)return;const up=keys.has('ArrowUp')||keys.has('w')||keys.has('W'),down=keys.has('ArrowDown')||keys.has('s')||keys.has('S'),left=keys.has('ArrowLeft')||keys.has('a')||keys.has('A'),right=keys.has('ArrowRight')||keys.has('d')||keys.has('D');let dx=(right?1:0)-(left?1:0),dy=(down?1:0)-(up?1:0);if(demoMode&&player.car&&demoSteering!==null){dx=Math.cos(demoSteering);dy=Math.sin(demoSteering);}let length=Math.hypot(dx,dy);if(player.car){if(length){dx/=length;dy/=length;player.speed+=(230-player.speed)*Math.min(1,dt*4.5);player.a=Math.atan2(dy,dx);}else{player.speed*=Math.pow(.045,dt);dx=Math.cos(player.a);dy=Math.sin(player.a);}const nx=player.x+dx*player.speed*dt,ny=player.y+dy*player.speed*dt,wall=isBlocked(nx,ny,14),ghost=demoMode&&demoGhostTimer>0,otherCar=!wall&&!ghost&&carInPath(nx,ny,15),pedestrian=!wall&&!ghost&&!otherCar&&personInPath(nx,ny,15);if(!wall&&!otherCar&&!pedestrian){player.x=nx;player.y=ny;}else{const impactSpeed=player.speed;let moved=false;if(!wall&&!ghost){if(!carInPath(nx,player.y,15)&&!personInPath(nx,player.y,15)){player.x=nx;moved=true;}if(!carInPath(player.x,ny,15)&&!personInPath(player.x,ny,15)){player.y=ny;moved=true;}}if(!moved){if(otherCar||pedestrian)bumpMessage(nx,ny,pedestrian?'BONK! WATCH THE CROSSWALK.':'CRUNCH! TRAFFIC IS NOT A SUGGESTION.');if(pedestrian&&impactSpeed>35&&time-lastPersonHit>1.5){lastPersonHit=time;raiseHeat(impactSpeed>155?2:1);say('PEDESTRIAN STRUCK · POLICE DISPATCHED.',2);}player.speed*=wall?-.12:-.2;}if(wall&&impactSpeed>75&&!taxiMode&&time-lastCrashHeat>2.5){lastCrashHeat=time;raiseHeat(1);}}}else{if(length){dx=dx/length*115*dt;dy=dy/length*115*dt;const nx=player.x+dx,ny=player.y+dy;if(dx&&!isBlocked(nx,player.y,7)&&!carInPath(nx,player.y,7)&&!personInPath(nx,player.y,7))player.x=nx;if(dy&&!isBlocked(player.x,ny,7)&&!carInPath(player.x,ny,7)&&!personInPath(player.x,ny,7))player.y=ny;player.a=Math.atan2(dy,dx);}}player.x=Math.max(20,Math.min(WORLD.w-20,player.x));player.y=Math.max(20,Math.min(WORLD.h-20,player.y));}function interact(){if(!active||arrestPending)return;if(player.car){if(taxiMode){say('CAB 12 IS ON A CALL. KEEP THE METER RUNNING.');return;}const exits=[player.a+Math.PI/2,player.a-Math.PI/2,player.a+Math.PI,player.a,player.a+Math.PI/4,player.a-Math.PI/4];let exit=null;for(const a of exits){const x=player.x+Math.cos(a)*27,y=player.y+Math.sin(a)*27;if(!isBlocked(x,y,7)&&!carInPath(x,y,7)&&!personInPath(x,y,7)){exit={x,y};break;}}player.car=false;player.speed=0;if(exit){player.x=exit.x;player.y=exit.y;}say('You exited your extremely trustworthy vehicle.');return;}const spot=findSafeRoadNode(player,0,true);if(spot&&Math.hypot(player.x-spot.x,player.y-spot.y)<95){const copSpot=findNearbyOfficerSpot(player);if(wanted===0)raiseHeat(1);else if(police.length<wanted)raiseHeat(1);const cop=police[0];if(cop){cop.x=copSpot.x;cop.y=copSpot.y;cop.a=Math.atan2(player.y-copSpot.y,player.x-copSpot.x);cop.carX=copSpot.x;cop.carY=copSpot.y;cop.carA=cop.a;cop.onFoot=true;cop.route=[];cop.routeIndex=0;cop.repath=0;cop.goalKey='';}arrestPending=true;player.speed=0;keys.clear();say('CAR THEFT ATTEMPT · OFFICER RESPONDING!',2);return;}say('No safe car nearby. Try another street corner.');}function talk(){if(busted)return;if(!active){if(!missionIntro.classList.contains('hidden'))startGame();else showMissionIntro();return;}say(missionData[missionIndex][1]+': “Keep it moving, pal!”');}
function raiseHeat(n){if(demoMode){wanted=0;escaped=0;police=[];updateHud();return;}wanted=Math.min(5,wanted+n);escaped=0;while(police.length<wanted){const spot=findSafeRoadNode(player,120,true)||findSafeRoadNode(player,0,false)||{x:player.x+150,y:player.y+150};police.push({x:spot.x,y:spot.y,a:0,route:[],routeIndex:0,repath:0,goalKey:''});}updateHud();}function objectives(){if(active&&taxiMode&&taxiPhase==='pickup'&&Math.hypot(player.x-taxiPickup.x,player.y-taxiPickup.y)<36){taxiPhase='dropoff';say('PASSENGER IN. TAKE '+taxiPassenger.toUpperCase()+' TO '+districtAt(taxiDrop.x,taxiDrop.y)+'.',3.2);updateHud();}else if(active&&taxiMode&&taxiPhase==='dropoff'&&Math.hypot(player.x-taxiDrop.x,player.y-taxiDrop.y)<36){cash+=taxiFare;taxiCompleted++;taxiPhase='waiting';taxiNextCall=2.3;say('FARE COLLECTED · +$'+taxiFare+' · STAND BY FOR DISPATCH.',2.2);saveGame();updateHud();}else if(active&&!taxiMode){const r=getRoute(),p=phase===0?r.start:r.end;if(Math.hypot(player.x-p.x,player.y-p.y)<32){if(phase===0){phase=1;say('GOT IT. NOW MAKE A VERY CASUAL DELIVERY.');}else finishMission();}}for(const d of drops)if(!d.got&&Math.hypot(player.x-d.x,player.y-d.y)<17){d.got=true;cash+=10;say('STREET CASH +$10');saveGame();}}
function finishMission(){active=false;phase=0;cash+=100+missionIndex*15;missionIndex++;saveGame();completed=missionIndex>=25;$('#clear-copy').textContent=completed?'Vinny’s tuna tin is safe. The city’s finest are still looking for their lunch. Your legend ends in a minor parking dispute.':'“'+missionData[missionIndex-1][0]+'” finished. +$'+(100+(missionIndex-1)*15)+' · '+missionData[missionIndex][1]+' has another favor.';$('#next-btn').innerHTML=completed?'BACK TO THE CITY <span>↩</span>':'NEXT JOB <span>▶</span>';clearScreen.classList.remove('hidden');updateHud();if(demoMode){if(completed)$('#demo-status').textContent='CAMPAIGN COMPLETE';else demoAdvanceTimer=2.25;}}
function showBusted(){if(demoMode){wanted=0;escaped=0;police=[];arrestPending=false;return;}if(busted)return;busted=true;arrestPending=false;active=false;keys.clear();player.speed=0;$('#bust-copy').textContent=taxiMode?'The police ended your shift. Bail is expensive; the passenger is still waiting.':'The officer caught up and put you in cuffs. The job is waiting after bail.';$('#bust-screen').classList.remove('hidden');$('#taxi-controls').classList.add('hidden');music.pause();}
