function updatePolice(dt){if(demoMode){wanted=0;escaped=0;police=[];if(busted||arrestPending){busted=false;arrestPending=false;$('#bust-screen').classList.add('hidden');}return;}if(wanted>0){let close=false;const goalNode=nearestRoadNode(player.x,player.y),goalKey=goalNode.ix+':'+goalNode.iy;for(const p of police){const distanceToPlayer=Math.hypot(player.x-p.x,player.y-p.y);if(!p.onFoot&&distanceToPlayer<112){p.onFoot=true;p.carX=p.x;p.carY=p.y;p.carA=p.a;p.repath=0;say('OFFICER OUT OF THE CAR! HANDS WHERE I CAN SEE THEM!',1.6);}p.repath-=dt;if(p.goalKey!==goalKey||p.repath<=0){p.route=streetRoute(p,player);p.routeIndex=0;p.goalKey=goalKey;p.repath=.55;}while(p.routeIndex<p.route.length&&Math.hypot(p.route[p.routeIndex].x-p.x,p.route[p.routeIndex].y-p.y)<22)p.routeIndex++;const target=p.route[p.routeIndex]||player,dx=target.x-p.x,dy=target.y-p.y,d=Math.hypot(dx,dy)||1;p.a=Math.atan2(dy,dx);const speed=p.onFoot?112+wanted*9:player.car?190+wanted*17:110+wanted*12,step=Math.min(d,speed*dt),nx=p.x+dx/d*step,ny=p.y+dy/d*step;if(!isBlocked(nx,ny,p.onFoot?7:13)){p.x=nx;p.y=ny;}else p.repath=0;const playerDist=Math.hypot(player.x-p.x,player.y-p.y);if(playerDist<155)close=true;if(playerDist<24){showBusted();return;}}if(!close){escaped+=dt;if(escaped>13){wanted=Math.max(0,wanted-1);escaped=0;police.pop();say(wanted?'THEY LOST YOU. HEAT DOWN.':'HEAT CLEARED. FIND A PAYPHONE.',2.5);updateHud();}}else escaped=0;}else police=[];}function updateTraffic(dt){for(const c of traffic){c.turnCooldown=Math.max(0,(c.turnCooldown||0)-dt);const roads=c.axis==='x'?ROAD_X:ROAD_Y,axisPos=c[c.axis];let crossing=roads[0],gap=Math.abs(axisPos-crossing);for(const road of roads){const d=Math.abs(axisPos-road);if(d<gap){gap=d;crossing=road;}}if(gap<8&&c.turnCooldown===0&&hash((c.id+1)*43+crossing+(c.axis==='x'?c.y:c.x))>.78){const nextAxis=c.axis==='x'?'y':'x',test={x:c.x,y:c.y};test[nextAxis]+=c.dir*65;if(!isBlocked(test.x,test.y,10)){c.axis=nextAxis;c.dir=hash(c.id*71+crossing+Math.floor(time))>.5?1:-1;c.turnCooldown=1.35;}}let desired=c.speed;for(const other of traffic){if(other===c||other.axis!==c.axis||Math.abs(other[c.axis==='x'?'y':'x']-c[c.axis==='x'?'y':'x'])>17)continue;const ahead=(other[c.axis]-c[c.axis])*c.dir;if(ahead>0&&ahead<58)desired=Math.min(desired,ahead<28?0:c.speed*.42);}c.currentSpeed=c.currentSpeed||c.speed;c.currentSpeed+=(desired-c.currentSpeed)*Math.min(1,dt*(desired<c.currentSpeed?5:1.4));const prev=c[c.axis],next=prev+c.dir*c.currentSpeed*dt;c[c.axis]=next;if(c.axis==='x'&&(c.x<-30||c.x>WORLD.w+30))c.x=c.dir>0?-30:WORLD.w+30;if(c.axis==='y'&&(c.y<-30||c.y>WORLD.h+30))c.y=c.dir>0?-30:WORLD.h+30;if(isWater(c.x,c.y)){c[c.axis]=prev;c.dir*=-1;c.currentSpeed=0;}}}
function updatePedestrians(dt){for(const [i,n] of npcs.entries()){n.t-=dt;if(n.t<0){n.t=1+hash(i+time)*3;n.a+=(hash(i+time*2)-.5)*2;}let threat=null,closest=155;const consider=(x,y,a,speed)=>{const d=Math.hypot(n.x-x,n.y-y);if(d<closest&&speed>22){closest=d;threat={x,y,a};}};if(active&&player.car)consider(player.x,player.y,player.a,player.speed);for(const c of traffic)consider(c.x,c.y,c.axis==='x'?(c.dir>0?0:Math.PI):(c.dir>0?Math.PI/2:-Math.PI/2),c.currentSpeed||c.speed);for(const p of police)if(!p.onFoot)consider(p.x,p.y,p.a,150);let pace=10;if(threat){const side=(n.x-threat.x)*-Math.sin(threat.a)+(n.y-threat.y)*Math.cos(threat.a);n.a=threat.a+(side>=0?1:-1)*Math.PI/2;n.fleeing=.55;pace=68;}else if(n.fleeing>0){n.fleeing=Math.max(0,n.fleeing-dt);pace=45;}const nx=n.x+Math.cos(n.a)*pace*dt,ny=n.y+Math.sin(n.a)*pace*dt,playerClear=Math.hypot(nx-player.x,ny-player.y)>(player.car?29:15);if(!isBlocked(nx,ny,5)&&!carInPath(nx,ny,4)&&!personInPath(nx,ny,5,n)&&playerClear){n.x=nx;n.y=ny;}else n.a+=threat?(hash(i+Math.floor(time*5))>.5?Math.PI/2:-Math.PI/2):Math.PI/2;}}
function update(dt){time+=dt;if(demoMode&&demoGhostTimer>0)demoGhostTimer=Math.max(0,demoGhostTimer-dt);if(demoMode&&demoIntroTimer>0){demoIntroTimer-=dt;$('#mission-ready').textContent='AUTO-START IN '+Math.max(1,Math.ceil(demoIntroTimer))+'…';if(demoIntroTimer<=0)startGame();}if(demoMode&&demoAdvanceTimer>0){demoAdvanceTimer-=dt;if(demoAdvanceTimer<=0){demoAdvanceTimer=0;showMissionIntro();demoIntroTimer=2.1;$('#mission-ready').textContent='AUTO-STARTING…';}}if(active){if(taxiMode&&taxiPhase==='waiting'){taxiNextCall-=dt;if(taxiNextCall<=0)issueTaxiCall();}if(demoMode)driveDemo(dt);movePlayer(dt);updatePolice(dt);objectives();}updateTraffic(dt);updatePedestrians(dt);camera.x=Math.max(0,Math.min(WORLD.w-W,camera.x+((player.x-W/2)-camera.x)*Math.min(1,dt*5)));camera.y=Math.max(0,Math.min(WORLD.h-H,camera.y+((player.y-H/2)-camera.y)*Math.min(1,dt*5)));if(toastTime>0){toastTime-=dt;if(toastTime<=0)toast.classList.add('hidden');}updateHud();}
function draw(){ctx.clearRect(0,0,W,H);drawWorld();}let last=performance.now();function loop(now){const dt=Math.min(.04,(now-last)/1000);last=now;update(dt*(demoMode?demoSpeed:1));draw();requestAnimationFrame(loop);}requestAnimationFrame(loop);
function keyDown(e){if(busted)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(demoMode)return;keys.add(e.key);if(e.repeat)return;if(e.key.toLowerCase()==='e')interact();if(e.key===' ')talk();}function keyUp(e){keys.delete(e.key);}window.addEventListener('keydown',keyDown);window.addEventListener('keyup',keyUp);window.addEventListener('blur',()=>keys.clear());
